import {setupStudio,studioView as expandedStudioView,studioTabs,sceneTools,entryTools,arcadeEntries} from './studio.js';
import {migrateProject,studioReport} from './studio-model.js';
import {cameraGlossary} from './camera.js';
glossary.push(...cameraGlossary);
import {acts,lessons,glossary,drills,sequences,reviewItems} from './curriculum.js';
import {STORAGE_KEY,initialState,blankProfile,blankProject,blankScene,uid,countWords,shuffle,lessonReady,hasDraft,reviewReady,fountain,projectReport,validateState,formatWarnings} from './engine.js';
import {example} from './example.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,storageError='',recoveryRaw='';try{const raw=localStorage.getItem(STORAGE_KEY);state=raw?validateState(JSON.parse(raw)):initialState();}catch(e){try{recoveryRaw=localStorage.getItem(STORAGE_KEY)||'';}catch{}state=initialState();storageError='The saved data could not be opened. Export a recovery copy before continuing; your original save has not been overwritten.';}
let screen='quest',mission=0,step=0,questionIndex=0,answerFeedback=null,studioTab='blueprint',game=null,drillIndex=null,timer=null,timerSeconds=0,timerRunning=false,toastTimer;
const profile=()=>state.profiles[state.active], project=()=>migrateProject(profile().projects[profile().project]);
const prog=i=>profile().progress[i]||(profile().progress[i]={answers:[],checks:[],complete:false});
const done=()=>lessons.filter(l=>profile().progress[l.id]?.complete).length;
const nextLesson=()=>lessons.findIndex(l=>!profile().progress[l.id]?.complete);
const xp=()=>done()*100+Object.values(profile().arcade.best).reduce((a,b)=>a+Number(b||0),0);
function save(){if(recoveryRaw)return false;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageError='';return true;}catch{storageError='Your browser could not save. Export a backup now to keep your writing.';toast(storageError);return false;}}
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3800);}
function download(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000);}
const slug=t=>t.replace(/[^\p{L}\p{N}_-]+/gu,'_').slice(0,80)||'My_short';
function btn(text,action,cls='',extra=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;}
function route(s){screen=s;game=null;answerFeedback=null;render();window.scrollTo(0,0);}
function drawArt(){return `<svg viewBox="0 0 460 300" role="img" aria-label="A storyboard, screenplay, and film slate on a writing desk"><defs><pattern id="grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" fill="none" stroke="#ffffff" stroke-opacity=".035"/></pattern><filter id="shadow"><feDropShadow dx="0" dy="9" stdDeviation="9" flood-opacity=".2"/></filter></defs><rect width="460" height="300" fill="url(#grid)"/><g transform="translate(76 45) rotate(-9 125 95)" filter="url(#shadow)"><rect width="205" height="214" rx="7" fill="#e9ebdb"/><text x="22" y="29" font-family="monospace" font-size="10" fill="#53664a">YOUR NEXT FILM</text><path d="M22 43H182M22 53H151" stroke="#b8c0a7" stroke-width="3"/><rect x="21" y="71" width="76" height="53" rx="3" fill="#cad2b6"/><rect x="108" y="71" width="76" height="53" rx="3" fill="#cad2b6"/><path d="M30 115 54 93 78 115M115 114h63M150 114V91m-10 7 10-8 10 8" fill="none" stroke="#758765" stroke-width="2"/><path d="M22 141h158m-158 10h135m-135 10h146m-146 20h70m14 0h75m-159 10h133" stroke="#b2bea3" stroke-width="3"/></g><g transform="translate(235 138) rotate(9 83 60)" filter="url(#shadow)"><rect width="160" height="107" rx="8" fill="#15251c"/><rect y="-12" width="160" height="30" rx="4" fill="#dce99a"/><path d="m15-12-15 30m52-30-17 30m52-30-17 30m52-30-17 30m50-30-16 30" stroke="#31472f" stroke-width="13"/><text x="16" y="44" font-family="monospace" font-size="8" fill="#b2c1a2">STORYFORGE PRODUCTIONS</text><path d="M15 53h129m-90 0v40m42-40v40" stroke="#3c5337"/><text x="16" y="68" font-family="monospace" font-size="7" fill="#9fb38d">SCENE</text><text x="65" y="68" font-family="monospace" font-size="7" fill="#9fb38d">TAKE</text><text x="112" y="68" font-family="monospace" font-size="7" fill="#9fb38d">ROLL</text><text x="21" y="91" font-family="monospace" font-size="22" fill="#edf4d7">01</text><text x="70" y="91" font-family="monospace" font-size="22" fill="#edf4d7">01</text><text x="117" y="91" font-family="monospace" font-size="22" fill="#edf4d7">A</text></g><g transform="translate(351 39) rotate(23)"><rect width="10" height="102" rx="3" fill="#dfba77"/><path d="m0 102 5 14 5-14" fill="#eadbc0"/><path d="m3 111 2 5 2-5" fill="#27382b"/></g><circle cx="356" cy="77" r="25" fill="none" stroke="#c2ce92" stroke-opacity=".2"/></svg>`;}
function header(title,sub,action=''){return `<div class="page-heading"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;}
function render(){
 const hash=screen==='lesson'?`#lesson/${mission+1}`:screen==='studio'?`#studio/${studioTab}`:`#${screen}`;if(location.hash!==hash)history.replaceState(null,'',hash);
 const nav=[['quest','✦','Your quest'],['arcade','◈','Practice arcade'],['studio','▤','My film'],['reference','▧','Craft library']];
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="./icon.svg" alt=""><div><strong>StoryForge</strong><small>THE SHORT FILM QUEST</small></div></div><nav class="nav" aria-label="Main navigation">${nav.map(([id,ic,t])=>`<button data-nav="${id}" class="${screen===id||(screen==='lesson'&&id==='quest')?'active':''}" ${screen===id?'aria-current="page"':''}><span class="symbol" aria-hidden="true">${ic}</span>${t}</button>`).join('')}</nav><div class="sidebar-note"><strong>One idea. Your own film.</strong>Learn a little. Practice it. Put it on the page.<a href="../">← WordRaiders</a></div></aside><div><header class="topbar"><span class="crumb">The writing room <span aria-hidden="true"> / </span> <b>${screen==='lesson'?'Mission '+(mission+1):nav.find(n=>n[0]===screen)?.[2]||'Your quest'}</b></span><div class="top-actions"><span class="xp">✦ ${xp()} XP</span><button class="profile-btn" data-action="profiles"><span class="avatar">${esc(profile().name.slice(0,1).toUpperCase())}</span><span>${esc(profile().name)}</span><span aria-hidden="true">⌄</span></button></div></header><main class="main" id="main">${storageError?`<div class="notice danger-text">${esc(storageError)} ${btn('Export recovery','recovery','small')}</div>`:''}${screen==='quest'?questView():screen==='lesson'?lessonView():screen==='arcade'?arcadeView():screen==='studio'?studioView():referenceView()}</main></div></div>`;
 if(screen==='arcade'&&drillIndex!==null&&!game)updateTimer();
}
function questView(){const n=nextLesson(),current=n<0?23:n,act=Math.floor(current/4),p=project();return header('Your first short starts here.',`A little craft. A little courage. A story only you can tell.`)+`<section class="hero"><div class="hero-content"><span class="tag">${n<0?'ALL 24 MISSIONS COMPLETE':`ACT ${act+1} · MISSION ${current+1} OF 24`}</span><h2>${n<0?'You wrote your way through.':lessons[current].title}</h2><p>${n<0?'Take your revised film into a read-through. Then bring your next idea to the page.':current===0?'Find the story hiding inside one of your ideas. Your first mission begins with a spark.':lessons[current].definition}</p>${btn(n<0?'Open my screenplay ↗':current===0?'Begin mission 01 →':'Continue your quest →','open-mission','lime',`data-id="${n<0?19:current}"`)}</div><div class="hero-art">${drawArt()}</div></section><div class="stats"><div class="stat"><span class="stat-icon">✦</span><div><strong>${done()}<span class="muted" style="font-size:14px"> / 24</span></strong><small>Missions completed</small></div></div><div class="stat"><span class="stat-icon">▤</span><div><strong>${p.scenes.filter(s=>s.action.trim()).length}</strong><small>Scenes on the page</small></div></div><div class="stat"><span class="stat-icon">◷</span><div><strong>${p.snapshots.length}</strong><small>Drafts preserved</small></div></div></div><div class="section-title"><h2>Your path to the final draft</h2><span>6 acts · Learn → Practice → Create</span></div><div class="act-grid">${acts.map((a,i)=>{const c=lessons.filter(l=>l.act===i&&profile().progress[l.id]?.complete).length;return `<button class="act-card ${act===i?'current':''}" data-action="open-act" data-id="${i}"><div class="act-top"><span class="act-icon" style="background:${a.color}">${a.icon}</span><span class="act-num">ACT 0${i+1}</span></div><h3>${a.name}</h3><p>${a.sub}</p><div class="act-foot"><span>${c===4?'✓ Act complete':act===i?'Your next chapter':`${c} of 4 missions`}</span><span aria-hidden="true">↗</span></div><div class="progress"><div style="width:${c/4*100}%"></div></div></button>`;}).join('')}</div><div class="bottom-note"><span style="font-size:23px">▤</span><div><b>Your ideas become your project.</b> Every writing mission adds to <b>${esc(p.title)}</b>. Save and switch film ideas in My film. Progress stays on this browser; use a backup to move devices.</div></div>`;}
function lessonView(){const l=lessons[mission],pr=prog(mission),a=acts[l.act],p=project();return header(l.title,`Act ${l.act+1}: ${a.name} · Mission ${mission+1} of 24`,btn('← Quest','quest','ghost'))+`<div class="split"><div><div class="lesson-nav" aria-label="Mission steps">${['01 Learn','02 See it work','03 Practice','04 Your film'].map((t,i)=>`<button data-action="lesson-step" data-id="${i}" class="${i===step?'active':''}" ${i===step?'aria-current="step"':''}>${t}</button>`).join('')}</div><section class="card lesson-text">${step===0?`<div class="definition"><b>${esc(l.term)}</b>${esc(l.definition)}</div>${l.teach.map(t=>`<p>${esc(t)}</p>`).join('')}<div class="spacer">${btn('Show me an example →','lesson-step','primary','data-id="1"')}</div>`:step===1?`<h3>See the difference</h3><div class="comparison"><div class="example"><span class="eyebrow muted">Starting point</span>${esc(l.before)}</div><div class="example good"><span class="eyebrow">A more useful choice</span>${esc(l.after)}</div></div><p class="why">${esc(l.why)}</p><div class="spacer">${btn('Try the practice →','lesson-step','primary','data-id="2"')}</div>`:step===2?lessonPractice(l,pr):`<span class="eyebrow muted">BUILDING: ${esc(p.title)}</span><h3 style="margin-top:12px">Put this into your film.</h3><p style="margin-bottom:17px">${esc(l.prompt)}</p>${mission===19?`<div class="notice">Write your actual scenes in the Screenplay tab. ${btn('Open screenplay','open-script','small')}</div>`:''}${mission===23?`<div class="notice">Finish your project’s evidence-based review. ${btn('Open screening room','open-review','small')}</div>`:''}<label class="field-label spacer" for="assignment">Your writing</label><textarea id="assignment" data-field="${l.field}" placeholder="Start in plain language. You can improve it later.">${esc(p.fields[l.field]||'')}</textarea><div class="row spread"><span class="fine" id="wordcount">${countWords(p.fields[l.field])} words</span><span class="saved" id="save-status">Autosaves on this browser</span></div>${entryTools()}<h4 class="spacer">Review your own work</h4><p class="fine">These are your judgments. The game checks completion, not artistic quality.</p>${l.checks.map((c,i)=>`<label class="check"><input type="checkbox" data-check="${i}" ${pr.checks[i]?'checked':''}>${esc(c)}</label>`).join('')}<div id="completion-area">${completionArea(l,pr,p)}</div>`}</section><p class="fine" style="margin-top:13px">Handbook connection: ${esc(l.ref)}. Examples and exercises are original.</p></div><aside class="stack"><div class="card"><span class="eyebrow muted">ACT 0${l.act+1}</span><h3 style="margin-top:10px">${a.name}</h3><div class="mission-list">${lessons.filter(x=>x.act===l.act).map(x=>`<button class="mission-item ${x.id===mission?'selected':''}" data-action="open-mission" data-id="${x.id}"><span class="number">${profile().progress[x.id]?.complete?'✓':String(x.id+1).padStart(2,'0')}</span><div><strong>${x.title}</strong><small>${profile().progress[x.id]?.complete?'Completed':'Learn · Practice · Create'}</small></div></button>`).join('')}</div></div><div class="notice"><b>Your own film is the final project.</b><p style="margin-top:7px">You can explore any mission. To finish one, answer both practice checks, write your response, and assess it against the two craft checks.</p></div>${btn('Open my film ↗','studio','ghost')}</aside></div>`;}
function completionArea(l,pr,p){const ready=lessonReady(l,pr,p);return `<div class="spacer">${btn(pr.complete?'Mission completed ✓':'Complete mission +100 XP','complete','primary',ready?'':'disabled')} ${pr.complete&&l.id<23?btn('Next mission →','open-mission','',`data-id="${l.id+1}"`):''}</div><p class="fine" style="margin-top:10px">${ready?'Ready to mark this practice complete.':`To complete: ${[!l.questions.every((_,i)=>pr.answers[i])?'answer both practice checks correctly':'',countWords(p.fields[l.field])<8?'write at least 8 words to get started':'',!l.checks.every((_,i)=>pr.checks[i])?'review both craft checks':'',l.id===19&&!hasDraft(p)?'write your screenplay scenes':'',l.id===23&&!reviewReady(p)?'finish the screening evidence and save a draft snapshot':''].filter(Boolean).join('; ')}.`}</p>`;}
function lessonPractice(l,pr){questionIndex=Math.min(questionIndex,l.questions.length-1);const q=l.questions[questionIndex];const order=pr.orders?.[questionIndex]||shuffle(q.options.map((_,i)=>i));if(!pr.orders)pr.orders={};pr.orders[questionIndex]=order;return `<div class="row spread"><span class="eyebrow muted">CHECK ${questionIndex+1} OF ${l.questions.length}</span><div class="step-dots">${l.questions.map((_,i)=>`<i class="${pr.answers[i]?'done':''}"></i>`).join('')}</div></div><h3 class="question">${esc(q.prompt)}</h3><div class="options">${order.map((o,j)=>`<button class="option ${answerFeedback?.option===o?(answerFeedback.correct?'correct':'wrong'):''}" data-action="lesson-answer" data-id="${o}" ${answerFeedback?'disabled':''}><span class="key">${String.fromCharCode(65+j)}</span>${esc(q.options[o])}</button>`).join('')}</div>${answerFeedback?`<div class="feedback ${answerFeedback.correct?'':'bad'}" role="status"><b>${answerFeedback.correct?'Yes — here’s why.':'Try that idea again.'}</b>${esc(q.why)}</div><div class="spacer">${answerFeedback.correct?btn(questionIndex===l.questions.length-1?'Apply it to my film →':'Next check →','next-check','primary'):btn('Try again','retry-check','primary')}</div>`:''}`;}
function studioView(){const p=project();return header('Your film, taking shape.','Keep the ideas. Build the scenes. Find the ending.',`<div class="row">${btn('New film +','new-project')}${btn('Export / backup','exports','primary')}</div>`)+`<div class="row spread" style="margin-bottom:20px"><label class="row"><span class="fine">CURRENT FILM</span><select aria-label="Current film" data-select="project">${profile().projects.map((x,i)=>`<option value="${i}" ${i===profile().project?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><span class="saved" id="save-status">Saved locally · backups keep it portable</span></div><nav class="studio-tabs" aria-label="Film workspace">${[['blueprint','Story blueprint'],['story','Notes → Story'],['screenplay','Screenplay'],...studioTabs.filter(([k])=>k!=='story'),['screening','Screening room'],['drafts','Saved drafts']].map(([k,t])=>btn(t,'studio-tab',studioTab===k?'active':'',`data-id="${k}"`)).join('')}</nav>${studioTab==='blueprint'?blueprintView(p):studioTab==='screenplay'?screenplayView(p):studioTab==='screening'?screeningView(p):studioTab==='drafts'?draftsView(p):expandedStudioView(studioTab)}`;}
function blueprintView(p){return entryTools()+`<div class="card" style="margin-bottom:20px"><label for="film-title" class="field-label">Working title</label><input id="film-title" class="project-title" data-edit="title" value="${esc(p.title)}"><p class="fine spacer">Your mission writing appears here. You can develop multiple ideas as separate films; the course progress belongs to your writer profile.</p></div>${acts.map((a,i)=>`<div class="section-title"><h2>${a.icon} ${a.name}</h2><span>Act ${i+1}</span></div><div class="fields-grid">${lessons.filter(l=>l.act===i).map(l=>`<div class="card field-card"><div class="row spread"><label class="field-label" for="field-${l.field}">${l.title}</label><button class="text-btn" data-action="open-mission" data-id="${l.id}">Lesson ↗</button></div><p class="fine" style="margin:0 0 12px">${esc(l.prompt)}</p><textarea id="field-${l.field}" data-field="${l.field}" placeholder="${esc(l.definition)}">${esc(p.fields[l.field]||'')}</textarea></div>`).join('')}</div>`).join('')}`;}
function screenplayView(p){return `<div class="row spread" style="margin-bottom:18px"><p class="fine">Write each scene. Move cards to test the order.</p><div class="row">${btn('Format help','format-help','small')}${btn('Preview / print','preview','small')}${btn('Save draft snapshot','snapshot','small primary')}</div></div><div class="notice" style="margin-bottom:18px">A scene heading tells us <b>inside/outside · place · time</b>. Write visible action below it. For speech, type an UPPERCASE character name, then their words on the next line. Leave a blank line between speakers.</div>${p.scenes.map((s,i)=>`<section class="card scene-card"><div class="row spread"><span class="eyebrow muted">SCENE ${String(i+1).padStart(2,'0')}</span><div class="row">${btn('↑','move-scene','small',`data-id="${i}" data-dir="-1" aria-label="Move scene ${i+1} up" ${i===0?'disabled':''}`)}${btn('↓','move-scene','small',`data-id="${i}" data-dir="1" aria-label="Move scene ${i+1} down" ${i===p.scenes.length-1?'disabled':''}`)}${btn('Remove','remove-scene','small danger',`data-id="${i}"`)}</div></div><label class="field-label spacer" for="heading-${i}">Scene heading</label><input id="heading-${i}" class="script-input" data-scene="${i}" data-prop="heading" placeholder="INT. KITCHEN - NIGHT" value="${esc(s.heading)}"><label class="field-label spacer" for="action-${i}">What we see and hear</label><textarea id="action-${i}" class="script-input" data-scene="${i}" data-prop="action" placeholder="MARA sets a key beside the untouched cup.">${esc(s.action)}</textarea><label class="field-label spacer" for="dialogue-${i}">Dialogue and further action (optional)</label><textarea id="dialogue-${i}" class="script-input" data-scene="${i}" data-prop="dialogue" placeholder="MARA&#10;You kept it.&#10;&#10;ELI&#10;It still works.">${esc(s.dialogue)}</textarea><label class="field-label spacer" for="turn-${i}">What changes in this scene? (private planning note)</label><input id="turn-${i}" data-scene="${i}" data-prop="turn" placeholder="Trust becomes suspicion." value="${esc(s.turn)}">${sceneTools(s)}</section>`).join('')}<div class="row">${btn('+ Add a scene','add-scene','primary')}${btn('Download .fountain','fountain')}</div><p class="fine spacer">Planning notes stay out of the screenplay export. Runtime depends on performance, pauses, and action; check it in a timed read-through.</p>`;}
function screeningView(p){const count=reviewItems.filter(([k])=>countWords(p.review[k])>=6).length;return `<div class="card" style="margin-bottom:20px"><div class="row spread"><div><span class="eyebrow muted">Evidence, not an automatic grade</span><h2 style="margin-top:10px">Is the story ready for a reader?</h2></div><strong class="review-score">${count}<span class="muted" style="font-size:18px"> / ${reviewItems.length}</span></strong></div><p class="fine spacer">Cite specific scenes or lines. These are self-assessments, not AI evaluations. For a stronger test, ask a willing reader to answer before seeing your notes.</p><div class="row spacer">${btn('Save current draft','snapshot')}${btn('Review screenplay','preview')}</div></div><div class="fields-grid">${reviewItems.map(([k,t,d])=>`<section class="card"><label class="field-label" for="review-${k}">${countWords(p.review[k])>=6?'✓ ':''}${t}</label><p class="fine" style="margin-bottom:12px">${d}</p><textarea id="review-${k}" data-review="${k}" placeholder="Record evidence, not just yes or no.">${esc(p.review[k]||'')}</textarea></section>`).join('')}</div><div class="card spacer"><h3>Final project check</h3><p class="fine">Complete a screenplay, preserve a draft snapshot, write table-read observations, revision notes, and a pitch in the blueprint, then support all twelve review points with evidence.</p><div class="spacer" id="review-button">${btn(p.reviewedAt?'Project review recorded ✓':'Record project review','finish-project','primary',reviewReady(p)?'':'disabled')}</div>${p.reviewedAt?`<p class="fine spacer">Reviewed ${esc(new Date(p.reviewedAt).toLocaleDateString())}. Keep revising when new feedback gives you a reason.</p>`:''}</div>${done()===24&&p.reviewedAt?`<div class="certificate spacer"><span class="eyebrow">StoryForge · First Film Finisher</span><h2>${esc(profile().name)}</h2><p>Completed 24 missions and an evidence-based project review.</p><h3 style="margin-top:16px">${esc(p.title)}</h3><p class="fine spacer">A finished learning journey. A beginning for your filmmaking.</p></div>`:''}`;}
function draftsView(p){return `<div class="notice" style="margin-bottom:20px">Snapshots preserve screenplay text at a moment in time. Download a full backup to preserve all projects, notes, and progress.</div>${btn('Save a new snapshot','snapshot','primary')}<div class="stack spacer">${p.snapshots.length?p.snapshots.slice().reverse().map((s,i)=>`<article class="card"><div class="row spread"><div><h3>Draft ${p.snapshots.length-i}</h3><span class="fine">${esc(new Date(s.date).toLocaleString())} · ${countWords(s.script)} words</span></div>${btn('Download draft','download-draft','',`data-id="${p.snapshots.length-i-1}"`)}</div><details class="spacer"><summary>Read this snapshot</summary><pre class="script-preview">${esc(s.script)}</pre></details></article>`).join(''):`<div class="card empty"><h3>Keep your first draft.</h3><p class="muted">Save a snapshot before a rewrite so you can see what changed.</p></div>`}</div>`;}
function arcadeView(){if(game)return gameView();if(drillIndex!==null)return drillView();return header('Practice the craft.','Short rounds for your instincts. Writing drills for your hands.')+arcadeEntries()+`<div class="game-grid">${[['spot','◈','Story Radar','Read a situation. Spot the choice that gives it a dramatic engine. Eight questions, with an explanation after every answer.'],['cut','✂','The Cutting Room','Practice visual action, scene turns, dialogue, and screenplay clarity. Eight challenges; no time pressure.'],['order','↗','Cause & Effect','Rebuild a five-beat story. Move the cards until the actions and consequences connect.'],['mix','✦','Final Cut Challenge','Ten mixed craft questions. Build a streak and see exactly which concepts need another pass.']].map(([id,ic,t,d])=>`<section class="card game-card"><span class="game-icon">${ic}</span><h3>${t}</h3><p>${d}</p><div class="row spread">${btn('Play round →','start-game','primary',`data-id="${id}"`)}<span class="fine">Best: ${profile().arcade.best[id]||0} XP</span></div></section>`).join('')}</div><div class="section-title"><h2>The writer’s gym</h2><span>Five drills from your handbook</span></div><div class="stack">${drills.map((d,i)=>`<button class="mission-item card" style="padding:20px" data-action="open-drill" data-id="${i}"><span class="number">${profile().drills[i]?.complete?'✓':i+1}</span><div style="flex:1"><strong>${d.name}</strong><small>${d.minutes} minute suggested session · Write and self-review</small></div><span aria-hidden="true">↗</span></button>`).join('')}</div>`;}
function startGame(mode){drillIndex=null;if(mode==='order'){const key='orderRound',n=profile().arcade[key]||0;profile().arcade[key]=n+1;const seq=sequences[n%sequences.length];game={mode,title:seq[0],items:shuffle(seq[1].map((text,id)=>({text,id}))),checked:false,finished:false,score:0};if(game.items.every((x,i)=>x.id===i))game.items.reverse();}else{let pool=lessons.filter(l=>mode==='spot'?l.id<12:mode==='cut'?l.id>=12&&l.id<=21:true).flatMap(l=>l.questions.map((q,i)=>({...q,id:`${l.id}-${i}`,lesson:l.id})));const seen=new Set(profile().arcade.seen);pool=[...shuffle(pool.filter(q=>!seen.has(q.id))),...shuffle(pool.filter(q=>seen.has(q.id)))];const length=mode==='mix'?10:8;game={mode,questions:pool.slice(0,length).map(q=>({...q,order:shuffle(q.options.map((_,i)=>i))})),index:0,score:0,streak:0,feedback:null,finished:false,missed:[]};}save();render();}
function gameView(){if(game.finished)return `<div class="arena">${header('Round complete.','Carry one thing you learned back to your film.')}<div class="card empty"><span class="eyebrow">${game.mode==='order'?'CAUSE & EFFECT':'CRAFT PRACTICE'}</span><h2 style="margin-top:20px">${game.score} XP</h2><p>${game.mode==='order'?'The order now follows the intended causal chain.':`${game.questions.length-game.missed.length} of ${game.questions.length} correct on your first answer.`}</p>${game.missed?.length?`<div class="notice" style="text-align:left">Revisit: ${[...new Set(game.missed)].map(i=>`<button class="text-btn" data-action="open-mission" data-id="${i}">${lessons[i].title}</button>`).join(' ')}</div>`:''}<div class="row" style="justify-content:center;margin-top:25px">${btn('Play another round','start-game','primary',`data-id="${game.mode}"`)}${btn('Back to arcade','arcade')}</div></div></div>`;
 if(game.mode==='order')return `<div class="arena">${header('Cause & Effect',game.title,btn('Exit round','arcade','ghost'))}<div class="arena-bar"><span>Build the causal chain</span><span class="arena-score">5 story beats</span></div><section class="card"><p>Move the cards into the story’s intended order. Ask: what causes the next action?</p><div class="sequence">${game.items.map((x,i)=>`<div class="sequence-item"><span class="fine">${i+1}</span><p>${esc(x.text)}</p>${btn('↑','move-beat','small',`data-id="${i}" data-dir="-1" aria-label="Move beat ${i+1} up" ${i===0?'disabled':''}`)}${btn('↓','move-beat','small',`data-id="${i}" data-dir="1" aria-label="Move beat ${i+1} down" ${i===4?'disabled':''}`)}</div>`).join('')}</div>${btn('Check the chain','check-order','primary')}${game.checked?`<div class="feedback bad" role="status"><b>Check the consequences.</b>${game.items.filter((x,i)=>x.id===i).length} of 5 beats are in the intended position. ${esc(orderHint())}</div>`:''}</section></div>`;
 const q=game.questions[game.index];return `<div class="arena">${header(game.mode==='spot'?'Story Radar':game.mode==='cut'?'The Cutting Room':'Final Cut Challenge','Choose the strongest craft decision.',btn('Exit round','arcade','ghost'))}<div class="arena-bar"><span>Challenge ${game.index+1} / ${game.questions.length}</span><span>Streak ${game.streak}</span><span class="arena-score">${game.score} XP</span></div><section class="card"><span class="eyebrow muted">${lessons[q.lesson].title}</span><h2 class="question">${esc(q.prompt)}</h2><div class="options">${q.order.map((o,j)=>`<button class="option ${game.feedback?.option===o?(game.feedback.correct?'correct':'wrong'):''}" data-action="game-answer" data-id="${o}" ${game.feedback?'disabled':''}><span class="key">${String.fromCharCode(65+j)}</span>${esc(q.options[o])}</button>`).join('')}</div>${game.feedback?`<div class="feedback ${game.feedback.correct?'':'bad'}" role="status"><b>${game.feedback.correct?'Good instinct.':'A useful adjustment.'}</b>${esc(q.why)}${!game.feedback.correct?`<p>Best answer: ${esc(q.options[q.answer])}</p>`:''}</div><div class="spacer">${btn(game.index===game.questions.length-1?'See results →':'Next challenge →','next-game','primary')}</div>`:''}</section></div>`;}
function orderHint(){const misplaced=game.items.find((x,i)=>x.id!==i);return misplaced.id===0?'Establish the goal or starting situation before attempts to handle it.':'Find the event that makes this action necessary; it should come earlier.';}
function finishGame(){game.finished=true;profile().arcade.best[game.mode]=Math.max(profile().arcade.best[game.mode]||0,game.score);save();render();}
function drillView(){const d=drills[drillIndex],v=profile().drills[drillIndex]||(profile().drills[drillIndex]={text:'',checks:[],complete:false});return header(d.name,'A writing workout. Take the time you need.',btn('← Arcade','close-drill','ghost'))+`<div class="split"><section class="card"><p>${d.prompt}</p><label class="field-label spacer" for="drill-writing">Your practice page</label><textarea class="drill-area" id="drill-writing" data-drill="text">${esc(v.text)}</textarea><p class="fine" id="save-status">Saved on this browser</p><h3 class="spacer">Craft check</h3>${d.checks.map((c,i)=>`<label class="check"><input type="checkbox" data-drill-check="${i}" ${v.checks[i]?'checked':''}>${c}</label>`).join('')}<div id="drill-complete">${btn(v.complete?'Drill recorded ✓':'Record this practice','complete-drill','primary',countWords(v.text)>=20&&d.checks.every((_,i)=>v.checks[i])?'':'disabled')}</div><p class="fine spacer">Write at least 20 words and review both checks. Completion records practice, not a quality score.</p></section><aside><div class="card"><span class="eyebrow muted">Optional focus timer</span><div class="timer spacer" id="timer-label">${d.minutes}:00</div><div class="row spacer">${btn(timerRunning?'Pause':'Start / resume','timer-toggle','small')}${btn('Reset','timer-reset','small')}</div><p class="fine spacer">The timer never submits, erases, or locks your writing.</p></div></aside></div>`;}
function updateTimer(){const el=$('#timer-label');if(el)el.textContent=`${Math.floor(timerSeconds/60)}:${String(timerSeconds%60).padStart(2,'0')}`;}
function referenceView(){return header('The craft library.','Definitions, a worked short, and the sources behind your quest.')+`<div class="card" style="margin-bottom:25px"><div class="row spread"><div><span class="eyebrow muted">A COMPLETE WORKED EXAMPLE</span><h2 style="margin-top:10px">The Spare Key</h2><p class="fine spacer">Follow an original idea through a logline, story spine, treatment, screenplay, and eight-frame study board. Create a study copy to edit the board.</p></div>${btn('Read the example →','example','primary')}</div></div><div class="card" style="margin-bottom:25px"><h3>Seven shapes for a short</h3><p class="fine" style="margin-bottom:15px">Pressure patterns from the handbook. Mix or leave them when your idea asks for another form.</p><div class="help">${[['The incident','An interruption forces a response. Example: a wrong delivery makes a neighbor choose whether to intervene.'],['The confrontation','People can no longer postpone a difficult exchange. Example: two siblings must divide one keepsake before the buyer arrives.'],['The process','A task reveals a person under pressure. Example: repairing a radio becomes a negotiation with grief.'],['The portrait under pressure','A focused experience reveals who a person is. Give the portrait a consequential moment rather than only a list of traits.'],['The fable','A simple chain follows a clear, sometimes strange rule. The action lets the meaning emerge.'],['The reversal','Later information changes our reading of earlier events. Plant fair clues and make the first viewing worthwhile.'],['The closed loop','Repeat an image or gesture after its meaning has changed. An empty chair can shift from rejection to a welcome.']].map(([t,d])=>`<details><summary>${t}</summary><p>${d}</p></details>`).join('')}</div></div><div class="section-title"><h2>Plain-language glossary</h2><span>${glossary.length} craft terms</span></div><label class="sr-only" for="glossary-search">Find a craft term</label><input id="glossary-search" placeholder="Find a term: subtext, scene, stakes…" style="margin-bottom:18px"><div class="glossary" id="glossary-results">${glossaryCards('')}</div><div class="section-title"><h2>Sources & approach</h2></div><div class="card"><p>This quest adapts your <i>Physics of Story</i> handbook into original lessons and exercises. Supplemental research fills the screenplay-format and portable-writing gaps.</p><ul class="source-list"><li><b>The Physics of Story: Short Film Handbook</b> (your supplied PDF, 20 pages). The six acts cover all twelve chapters, the worksheet, and all five writing drills.</li><li><a class="inline" href="https://www.oscars.org/sites/oscars/files/scriptsample.pdf" target="_blank" rel="noopener">Academy of Motion Picture Arts and Sciences — screenplay format guide</a>. Used for basic page conventions and its emphasis on readability rather than a single rigid format.</li><li><a class="inline" href="https://fountain.io/syntax/" target="_blank" rel="noopener">Fountain — official syntax</a>. Used for portable plain-text screenplay export.</li></ul><p class="fine">Research checked September 21, 2026. Story formulas, cutting targets, and time estimates are presented as heuristics. Creative responses are self-reviewed; this app does not use an AI judge or guarantee artistic or professional readiness. A complete, revised short and outside feedback are the intended outcome.</p></div>`;}
function glossaryCards(query){const found=glossary.filter(([t,d])=>(t+' '+d).toLowerCase().includes(query.toLowerCase()));return found.length?found.map(([t,d])=>`<article class="card"><h3>${t}</h3><p>${d}</p></article>`).join(''):'<p class="muted">No matching terms. Try a shorter word.</p>';}
function modal(html){const wrap=document.createElement('div');wrap.className='modal-wrap';wrap.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="StoryForge dialog">${html}<div class="spacer">${btn('Close','close-modal','ghost')}</div></section>`;document.body.append(wrap);wrap.querySelector('input,button,select')?.focus();}
function closeModal(){document.querySelectorAll('.modal-wrap').forEach(x=>x.remove());}
function exportsModal(){modal(`<h2>Keep your work.</h2><p>Writing is saved in this browser. A full backup moves your writers, projects, drafts, and progress to another device.</p><div class="stack">${btn('Download full backup (.json)','backup','primary')}${btn('Download screenplay (.fountain)','fountain')}${btn('Download story workbook (.md)','workbook')}${btn('Preview / print screenplay','preview')}</div><label class="field-label spacer" for="backup-import">Import a StoryForge backup</label><input id="backup-import" type="file" accept=".json,application/json"><p class="fine">Imported writers are added as separate profiles. Existing work is preserved.</p>`);}
function scriptHTML(p){return `<div class="title">${esc(p.title)}<br><small>Written by ${esc(profile().name)}</small></div>${p.scenes.map(s=>`<div class="heading">${esc(s.heading.toUpperCase())}</div><div class="action">${esc(s.action)}</div>${s.dialogue.trim()?`<div class="dialogue">${esc(s.dialogue)}</div>`:''}`).join('')}`;}
function preview(){closeModal();const wrap=document.createElement('div');wrap.className='modal-wrap';wrap.innerHTML=`<section class="modal" style="width:850px" role="dialog" aria-modal="true" aria-label="Screenplay preview"><div class="row spread"><h2>Script preview</h2>${btn('Close','close-modal','small')}</div><p class="fine spacer">A reading preview. Use the Fountain export in screenplay software for final pagination and submission formatting.</p>${formatWarnings(project()).length?`<div class="notice spacer">${formatWarnings(project()).map(esc).join('<br>')}</div>`:''}<div class="row spacer">${btn('Print / save as PDF','print','primary')}${btn('Download Fountain','fountain')}</div><div class="script-preview spacer">${scriptHTML(project())}</div></section>`;document.body.append(wrap);wrap.querySelector('button')?.focus();}
function showExample(){closeModal();const wrap=document.createElement('div');wrap.className='modal-wrap';wrap.innerHTML=`<section class="modal" style="width:850px" role="dialog" aria-modal="true" aria-label="Worked example"><div class="row spread"><h2>${example.title}</h2>${btn('Close','close-modal','small')}</div><p class="fine">An original demonstration, not a model you must imitate.</p><h3>Logline</h3><p>${example.logline}</p><h3>Story spine</h3><div class="example spacer">${example.spine}</div><h3 class="spacer">Treatment</h3><p class="spacer">${example.treatment}</p><h3>Screenplay</h3><div class="script-preview spacer">${example.scenes.map(s=>`<div class="heading">${s.heading}</div><div class="action">${s.action}</div><div class="dialogue">${s.dialogue}</div>`).join('')}</div><h3 class="spacer">Inside the choices</h3>${example.notes.map(([t,d])=>`<h4 class="spacer">${t}</h4><p>${d}</p>`).join('')}<div class="row spacer">${btn('Create a separate study copy','copy-example','primary')}${btn('Close','close-modal')}</div></section>`;document.body.append(wrap);wrap.querySelector('button')?.focus();}
function profilesModal(){modal(`<h2>Your writing desk</h2><p>Writer profiles keep separate projects and progress on this browser. They are not password-protected cloud accounts.</p><div class="stack">${state.profiles.map((p,i)=>btn(`${i===state.active?'✓ ':''}${esc(p.name)}`,'switch-profile',i===state.active?'primary':'',`data-id="${i}"`)).join('')}</div><label for="writer-name" class="field-label spacer">New writer name</label><input id="writer-name" maxlength="60" placeholder="Your name">${btn('Add writer','add-profile')}<div class="row spacer">${btn('Rename current writer','rename-profile','small')}${btn('Backup / import','exports','small')}</div>`);}
function completeLesson(){const l=lessons[mission],pr=prog(mission);if(!lessonReady(l,pr,project()))return;const already=pr.complete;pr.complete=true;pr.projectId=project().id;pr.date=new Date().toISOString();save();toast(already?'Your mission work is updated.':'Mission complete · +100 XP');render();}
function saveSnapshot(){if(!hasDraft(project())){toast('Add a heading and action to every scene before saving a draft.');return;}project().snapshots.push({id:uid(),date:new Date().toISOString(),script:fountain(project(),profile().name)});save();toast('Draft snapshot preserved.');if(screen==='studio')render();}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){drillIndex=null;route(nav.dataset.nav);return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;switch(a){
case 'quest':case 'studio':case 'arcade':case 'reference':drillIndex=null;route(a);break;
case 'open-mission':mission=Number(id);step=0;questionIndex=0;answerFeedback=null;screen='lesson';game=null;closeModal();render();window.scrollTo(0,0);break;
case 'open-act':{const ls=lessons.filter(l=>l.act===Number(id));mission=(ls.find(l=>!profile().progress[l.id]?.complete)||ls[0]).id;step=0;questionIndex=0;answerFeedback=null;screen='lesson';render();window.scrollTo(0,0);break;}
case 'lesson-step':step=Number(id);answerFeedback=null;questionIndex=0;render();break;
case 'lesson-answer':{if(answerFeedback)return;const q=lessons[mission].questions[questionIndex],correct=Number(id)===q.answer;answerFeedback={option:Number(id),correct};prog(mission).answers[questionIndex]=correct;save();render();break;}
case 'retry-check':answerFeedback=null;render();break;
case 'next-check':answerFeedback=null;if(questionIndex===lessons[mission].questions.length-1)step=3;else questionIndex++;render();break;
case 'complete':completeLesson();break;
case 'open-script':screen='studio';studioTab='screenplay';render();window.scrollTo(0,0);break;
case 'open-review':screen='studio';studioTab='screening';render();window.scrollTo(0,0);break;
case 'studio-tab':studioTab=id;render();break;
case 'new-project':modal(`<h2>A new film.</h2><p>Give this idea a working title. You can change it later.</p><input id="new-title" aria-label="New film title" maxlength="120" placeholder="Working title">${btn('Create film','create-project','primary')}`);break;
case 'create-project':{const name=$('#new-title').value.trim();if(!name){toast('Give the film a working title.');return;}profile().projects.push(blankProject(name));profile().project=profile().projects.length-1;save();closeModal();screen='studio';studioTab='blueprint';render();break;}
case 'add-scene':project().scenes.push(blankScene());project().reviewedAt=null;save();render();setTimeout(()=>document.querySelectorAll('.scene-card')[project().scenes.length-1]?.scrollIntoView({block:'center'}),0);break;
case 'move-scene':{const i=Number(id),j=i+Number(b.dataset.dir);if(j<0||j>=project().scenes.length)return;[project().scenes[i],project().scenes[j]]=[project().scenes[j],project().scenes[i]];project().reviewedAt=null;save();render();break;}
case 'remove-scene':modal(`<h2>Remove scene ${Number(id)+1}?</h2><p>This removes the scene from your current draft. Saved draft snapshots are preserved.</p>${btn('Remove this scene','confirm-remove-scene','danger',`data-id="${id}"`)}`);break;
case 'confirm-remove-scene':project().scenes.splice(Number(id),1);if(!project().scenes.length)project().scenes.push(blankScene());project().reviewedAt=null;save();closeModal();render();break;
case 'snapshot':saveSnapshot();break;
case 'download-draft':download(`${slug(project().title)}_draft_${Number(id)+1}.fountain`,project().snapshots[Number(id)].script);break;
case 'exports':closeModal();exportsModal();break;
case 'backup':download('StoryForge_backup_'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json');break;
case 'recovery':download('StoryForge_recovery.json',recoveryRaw||JSON.stringify(state,null,2),'application/json');if(recoveryRaw)modal(`<h2>Recovery copy downloaded.</h2><p>Keep that file. You may continue with a new save, or close this message to leave the existing browser data untouched.</p>${btn('Start a new save','reset-after-recovery','primary')}`);break;
case 'reset-after-recovery':recoveryRaw='';save();closeModal();render();break;
case 'fountain':download(slug(project().title)+'.fountain',fountain(project(),profile().name));break;
case 'workbook':download(slug(project().title)+'_workbook.md',projectReport(project(),profile().name)+studioReport(project()),'text/markdown');break;
case 'preview':preview();break;
case 'print':document.querySelector('.print-only')?.remove();{const el=document.createElement('section');el.className='print-only';el.innerHTML=scriptHTML(project());document.body.append(el);window.print();}break;
case 'close-modal':closeModal();break;
case 'profiles':profilesModal();break;
case 'switch-profile':state.active=Number(id);save();closeModal();screen='quest';drillIndex=null;render();break;
case 'add-profile':{const name=$('#writer-name').value.trim();if(!name){toast('Enter a writer name.');return;}state.profiles.push(blankProfile(name));state.active=state.profiles.length-1;save();closeModal();route('quest');break;}
case 'rename-profile':closeModal();modal(`<h2>Writer name</h2><input id="rename-writer" aria-label="Writer name" maxlength="60" value="${esc(profile().name)}">${btn('Save name','save-name','primary')}`);break;
case 'save-name':{const name=$('#rename-writer').value.trim();if(!name)return;profile().name=name;save();closeModal();render();break;}
case 'finish-project':if(reviewReady(project())){project().reviewedAt=new Date().toISOString();save();toast('Project review recorded. Bring your short to a reader.');render();}break;
case 'format-help':modal(`<h2>A readable screenplay</h2><p><b>INT. KITCHEN - NIGHT</b><br>INT. means inside. EXT. means outside. Then name the place and time.</p><p><b>Action</b><br>Describe what we see or hear, in present tense.</p><p><b>MARA</b><br>A speaker’s name goes on its own line, followed immediately by their dialogue.</p><p>Leave a blank line between blocks. Parentheses can give a brief delivery or action note. Use them sparingly. Scene-planning notes do not appear in the export.</p><p class="fine">The preview is for reading. Fountain files can be opened in compatible screenplay software for professional pagination.</p>`);break;
case 'example':showExample();break;
case 'copy-example':{const p=blankProject('The Spare Key — study copy');p.fields.logline=example.logline;p.fields.spine=example.spine;p.fields.treatment=example.treatment;p.scenes=example.scenes.map(s=>({...s,id:uid()}));migrateProject(p);p.scenes.forEach((s,i)=>{s.frames=['WS','CU'].map(size=>({id:uid(),sceneId:s.id,shotSize:size,angle:'Eye level',perspective:size==='CU'?'Insert':'Objective',move:'Static',duration:3,transition:'Cut',imageRef:size==='WS'?(i===2?'assets/kitchen.svg':'assets/hallway.svg'):['assets/key.svg','assets/door.svg','assets/alone-at-table.svg','assets/key.svg'][i],caption:size==='WS'?s.action.split('\n')[0]:['Mara leaves the key on the table.','Ruth grips the handle from the other side.','The screwdriver clatters beside the mug.','Ruth hangs the key on its hook.'][i],dialogueBeat:'',characterId:'',aiPrompt:''}));});profile().projects.push(p);profile().project=profile().projects.length-1;save();closeModal();screen='studio';studioTab='screenplay';render();break;}
case 'start-game':startGame(id);break;
case 'game-answer':{if(!game||game.feedback)return;const q=game.questions[game.index],correct=Number(id)===q.answer;game.feedback={correct,option:Number(id)};if(correct){game.streak++;game.score+=10+Math.min(game.streak-1,5)*2;}else{game.streak=0;game.missed.push(q.lesson);}const seen=profile().arcade.seen;profile().arcade.seen=[...seen.filter(x=>x!==q.id),q.id].slice(-48);save();render();break;}
case 'next-game':if(!game?.feedback)return;if(game.index===game.questions.length-1)finishGame();else{game.index++;game.feedback=null;render();}break;
case 'move-beat':{const i=Number(id),j=i+Number(b.dataset.dir);if(j<0||j>=game.items.length)return;[game.items[i],game.items[j]]=[game.items[j],game.items[i]];game.checked=false;render();break;}
case 'check-order':if(game.items.every((x,i)=>x.id===i)){game.score=50;finishGame();}else{game.checked=true;render();}break;
case 'open-drill':drillIndex=Number(id);timerSeconds=drills[drillIndex].minutes*60;timerRunning=false;clearInterval(timer);render();break;
case 'close-drill':drillIndex=null;timerRunning=false;clearInterval(timer);render();break;
case 'complete-drill':{const v=profile().drills[drillIndex];if(countWords(v.text)<20||!drills[drillIndex].checks.every((_,i)=>v.checks[i]))return;v.complete=true;save();toast('Writing practice recorded.');render();break;}
case 'timer-toggle':if(timerSeconds<=0)timerSeconds=drills[drillIndex].minutes*60;timerRunning=!timerRunning;clearInterval(timer);if(timerRunning){let deadline=Date.now()+timerSeconds*1000;timer=setInterval(()=>{timerSeconds=Math.max(0,Math.ceil((deadline-Date.now())/1000));updateTimer();if(!timerSeconds){timerRunning=false;clearInterval(timer);toast('Focus session finished. Keep writing if you like.');}},250);}render();break;
case 'timer-reset':timerRunning=false;clearInterval(timer);timerSeconds=drills[drillIndex].minutes*60;render();break;
}});
document.addEventListener('input',e=>{const el=e.target;
 if(el.id==='glossary-search'){$('#glossary-results').innerHTML=glossaryCards(el.value);return;}
 let dirty=false;if(el.dataset.field){project().fields[el.dataset.field]=el.value;project().reviewedAt=null;dirty=true;if($('#wordcount'))$('#wordcount').textContent=countWords(el.value)+' words';if(screen==='lesson'&&step===3)$('#completion-area').innerHTML=completionArea(lessons[mission],prog(mission),project());}
 if(el.dataset.edit==='title'){project().title=el.value||'Untitled short';dirty=true;}
 if(el.dataset.scene!==undefined){project().scenes[Number(el.dataset.scene)][el.dataset.prop]=el.value;project().reviewedAt=null;dirty=true;}
 if(el.dataset.review){project().review[el.dataset.review]=el.value;project().reviewedAt=null;dirty=true;$('#review-button').innerHTML=btn('Record project review','finish-project','primary',reviewReady(project())?'':'disabled');}
 if(el.dataset.drill){profile().drills[drillIndex].text=el.value;dirty=true;updateDrillCompletion();}
 if(dirty){project().updated=Date.now();const ok=save();if($('#save-status'))$('#save-status').textContent=ok?'Saved on this browser':'Not saved — export a backup';}
});
function updateDrillCompletion(){const v=profile().drills[drillIndex];$('#drill-complete').innerHTML=btn(v.complete?'Drill recorded ✓':'Record this practice','complete-drill','primary',countWords(v.text)>=20&&drills[drillIndex].checks.every((_,i)=>v.checks[i])?'':'disabled');}
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.check!==undefined){prog(mission).checks[Number(el.dataset.check)]=el.checked;save();$('#completion-area').innerHTML=completionArea(lessons[mission],prog(mission),project());}if(el.dataset.drillCheck!==undefined){profile().drills[drillIndex].checks[Number(el.dataset.drillCheck)]=el.checked;save();updateDrillCompletion();}if(el.dataset.select==='project'){profile().project=Number(el.value);save();render();}if(el.id==='backup-import'&&el.files[0]){try{if(el.files[0].size>10000000)throw Error('This backup is too large (10 MB maximum).');const imported=validateState(JSON.parse(await el.files[0].text()));if(state.profiles.length+imported.profiles.length>100)throw Error('This import exceeds the limit of 100 writer profiles.');for(const p of imported.profiles){p.id=uid();p.name+=' (imported)';state.profiles.push(p);}state.active=state.profiles.length-imported.profiles.length;save();closeModal();route('quest');toast('Backup imported as separate writer profiles.');}catch(err){toast(err.message||'Could not import this backup. Your existing work is unchanged.');}el.value='';}});
document.addEventListener('keydown',e=>{const m=document.querySelector('.modal-wrap');if(e.key==='Escape'){closeModal();return;}if(m&&e.key==='Tab'){const f=[...m.querySelectorAll('button,input,select,textarea,a[href],summary')].filter(x=>!x.disabled),first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY)toast('Another tab changed this save. Export your current work, then reload to avoid overwriting it.');});
setupStudio({project,profile,lessons,drills,acts,save,render,toast,download,slug,modal,closeModal,blankScene,shuffle,go:tab=>{closeModal();screen='studio';studioTab=tab;render();window.scrollTo(0,0);}});
function readRoute(){const parts=location.hash.slice(1).split('/');if(parts[0]==='lesson'&&Number.isInteger(Number(parts[1]))&&Number(parts[1])>=1&&Number(parts[1])<=24){screen='lesson';mission=Number(parts[1])-1;step=0;}else if(parts[0]==='studio'){screen='studio';studioTab=['blueprint','screenplay','screening','drafts',...studioTabs.map(([k])=>k)].includes(parts[1])?parts[1]:'blueprint';}else if(['quest','arcade','reference'].includes(parts[0]))screen=parts[0];}
window.addEventListener('hashchange',()=>{readRoute();render();});
readRoute();render();
